content.content:
// API contract between the DealScope FastAPI server (src/dealscope/api) and this frontend.
// All user-facing wording is produced server-side in plain language; the UI must not show raw
// internal codes (reason codes, stage enums) except inside an optional "technical details" disclosure.

export type RunMode = "live" | "synthetic";
export type Tone = "good" | "neutral" | "caution" | "bad" | "info";

export interface ProviderStatus {
  key: "crustdata" | "llm" | "neatlogs" | "jobs_pricing";
  label: string; // e.g. "Company data (Crustdata)"
  connected: boolean;
  detail: string; // e.g. "Connected" / "Model: gemini-3.1-flash-lite" / "Not configured"
}

export interface BudgetSummary {
  spendable: number; // credits allowed for product use (total minus reserve)
  estimated_used: number;
  actual_used: number; // confirmed from provider response headers
  reserved: number;
  remaining: number;
  unknown_calls: number;
  reserve: number; // credits held back and never spent
  total: number;
}

export interface StatusResponse {
  providers: ProviderStatus[];
  live_budget: BudgetSummary;
  max_case_credits: number;
  live_available: boolean; // false when no Crustdata key: live runs are refused, never faked
}

export interface Scenario {
  id: string; // "scenario_a" | "scenario_b" | "synthetic_case"
  label: string;
  description: string;
  target_domain: string;
  competitor_domains: string[];
  deal_thesis: string;
}

export interface FaultOption {
  id: string; // "none" | "retry_success" | "retry_exhausted" | "auth_failure"
  label: string;
  description: string;
}

export interface IdentityCandidate {
  name: string | null;
  primary_domain: string | null;
  employee_count_range: string | null;
}

export interface IdentityResult {
  domain: string;
  ok: boolean;
  status: "ok" | "ambiguous" | "mismatch" | "no_match" | "error";
  resolved_name: string | null;
  match_count: number;
  message: string; // plain-language explanation, e.g. "23 different companies use this domain..."
  candidates: IdentityCandidate[];
}

export interface CreateCaseRequest {
  target_domain: string;
  competitor_domains: string[];
  deal_thesis: string;
  lookback_months: number;
  max_case_credits: number;
  mode: RunMode;
  scenario_id?: string; // synthetic only
  fault_id?: string; // synthetic only
}

export interface CreateCaseResponse {
  case_id: string;
}

export interface CaseListItem {
  case_id: string;
  target: string;
  mode: RunMode;
  status_label: string; // "Complete", "Partial - can resume", "Running", "Failed"
  tone: Tone;
  risk_label: string; // "Watch (32/100)" or "Not enough evidence"
  updated_at: string; // ISO
}

export interface Assessment {
  risk_score: number | null; // 0-100, null when coverage < 60%
  risk_band: string | null; // "Low signal" | "Watch" | "Elevated" | "High signal"
  risk_tone: Tone;
  headline: string; // one plain sentence summarising the result
  coverage_pct: number;
  coverage_label: string; // "Enough evidence to score" / "Provisional" / "Not enough evidence"
  confidence: number; // 0-100, evidence quality (separate from risk)
  confidence_label: string; // "High" | "Medium" | "Low"
  explainer: string; // how to read risk vs coverage vs confidence
}

export interface SignalView {
  id: string; // "S1".."S5"
  name: string; // plain name, e.g. "Engineering team vs. company growth"
  question: string; // the question this signal answers
  weight_pct: number;
  scored: boolean;
  score: number | null;
  band: string | null; // band label for this signal score
  tone: Tone;
  status_label: string; // "Scored" | "Partly scored (thin data)" | "Not scored"
  confidence: number;
  finding: string; // plain-language result, built from reason codes and raw measures
  why_it_matters: string;
  limitations: string[];
  evidence_ids: string[];
  technical: { reason_codes: string[]; state: string };
}

export interface EvidenceRef {
  id: string;
  label: string; // "Company profile - notion.com" / "Job posting - Staff SRE"
  date: string | null;
  source: string; // "Crustdata /job/search" or "Synthetic fixture"
}

export interface FindingView {
  id: string;
  kind: "Fact" | "Interpretation" | "Hypothesis" | "Question";
  severity: "low" | "medium" | "high";
  text: string;
  verification: "Verified" | "Verified with caveats";
  caveats: string[];
  evidence: EvidenceRef[];
  counter_evidence: EvidenceRef[];
  alternatives: string[];
  limitations: string[];
}

export interface StepView {
  n: number;
  at: string; // ISO timestamp
  kind: "plan" | "tool" | "retry" | "score" | "stage" | "resume" | "blocked" | "note";
  title: string; // plain, e.g. "Checked open engineering roles at notion.com"
  detail: string; // plain explanation, e.g. "Found 25 postings; 14 were reposted."
  actor: string; // "AI planner" | "Rule-based planner" | "Baseline" | "System" | "Retry policy"
  tone: Tone;
  credits: string | null; // e.g. "2 credits (confirmed)" / "from cache, 0 credits"
}

export interface CompanyRow {
  domain: string;
  role: "Target" | "Peer";
  name: string | null;
  headcount: number | null;
  total_growth: Record<string, number>; // period label ("3m","6m","12m") -> percent
  engineering_headcount: number | null;
  engineering_growth: Record<string, number>;
  open_jobs: number | null;
  data_quality_flags: string[]; // plain sentences
  evidence_id: string;
}

export interface PersonRow {
  ref: string; // opaque, never a name
  role_group: string; // plain: "Technical leadership"
  title_at_target: string | null;
  left_target: string | null; // "2026-05" or null if still there / unknown
  status: string; // "Left in lookback window" | "Left earlier" | "Still at target" | "End date unknown"
  now_at: string | null;
  now_at_competitor: boolean;
  evidence_id: string;
}

export interface JobRow {
  title: string;
  capability: string; // plain: "Security"
  posted: string | null;
  reposted: boolean | null;
  openings: number | null;
  url: string | null;
  evidence_id: string;
}

export interface CreditsView {
  cap: number;
  estimated_used: number;
  actual_used: number;
  reserved: number;
  remaining: number;
  unknown_calls: number;
  simulated: boolean; // synthetic runs: simulated accounting, no real credits
}

export interface VerificationView {
  published: number;
  verified: number;
  with_caveats: number;
  rejected: number;
  grounded_rate: number | null; // 0-1
  rejected_reasons: { reason: string; count: number }[]; // plain reasons
  ai_draft_used: boolean; // false when the AI write-up was unavailable and only rule-based findings are shown
}

export interface CaseView {
  case_id: string;
  mode: RunMode;
  synthetic: boolean;
  target: string;
  peers: string[];
  thesis: string;
  lookback_months: number;
  running: boolean;
  status_label: string;
  status_tone: Tone;
  status_detail: string; // plain explanation of how/why the run ended
  can_resume: boolean;
  current_question: string | null;
  planner_turns: number;
  tool_calls: number;
  assessment: Assessment | null; // null until the first scoring
  signals: SignalView[];
  findings: FindingView[];
  questions: string[]; // diligence questions for management
  steps: StepView[];
  companies: CompanyRow[];
  people: PersonRow[];
  jobs: JobRow[];
  credits: CreditsView;
  verification: VerificationView | null;
  trace_ids: string[];
  llm_model: string | null;
  updated_at: string;
  report_available: boolean;
}

// ---------------------------------------------------------------------------
// v0.3 additions: featured (recorded) cases, cancel, partner evidence summary
// ---------------------------------------------------------------------------

// GET /api/featured -> FeaturedCase[]  (finished live cases bundled with the repo; open without spending credits)
export interface FeaturedCase {
  case_id: string;
  label: string; // e.g. "notion.com vs coda.io, airtable.com, clickup.com"
  description: string;
  recorded_at: string; // ISO date of the live run
}

// POST /api/cases/{id}/cancel -> CreateCaseResponse  (409 when the case is not running)
// After cancelling, the case ends with status_label "Stopped by you" and can be resumed.

export interface NeatlogsRun {
  label: string; // "Live investigation - airtable.com"
  kind: "live" | "failure" | "eval";
  case_id: string | null;
  trace_ids: string[];
  summary: string; // plain sentence with the outcome
}

export interface EvalRow {
  scenario: string; // "A" | "B"
  variant: "baseline" | "improved";
  trace_id: string | null;
  draft_claims: number;
  draft_rejected: number;
  draft_verified: number;
  draft_with_caveats: number;
  published: number;
  tool_calls: number;
}

export interface EvidenceFile {
  label: string;
  path: string; // repo-relative "evidence/..."; images and PDFs load from /api/evidence/<path after "evidence/">
}

export interface EvidenceSummary {
  neatlogs: {
    runs: NeatlogsRun[];
    eval_rows: EvalRow[];
    eval_reading: string; // honest one-paragraph interpretation
    screenshots: EvidenceFile[];
  };
  entire: {
    checkpoints: { commit: string; subject: string; checkpoint: string }[];
    transcript_path: string | null;
    notes: string[];
  };
  cfo: {
    scenarios: {
      name: string;
      revenue: string;
      audits: string;
      gross_margin: string;
      contribution_margin: string;
      peak_funding_need: string;
    }[];
    unit_cost: string; // e.g. "$94.65 per audit (QA $90, tooling $2, Crustdata $2.60, LLM $0.05)"
    pricing: string[];
    notes: string[];
    files: EvidenceFile[];
  };
  crustdata: {
    total: number;
    reserve: number;
    spendable: number;
    actual_used: number;
    estimated_used: number;
    remaining: number;
    prices: { endpoint: string; credits: string }[];
    notes: string[];
  };
}
import type {
  CaseListItem,
  CaseView,
  CreateCaseRequest,
  CreateCaseResponse,
  FaultOption,
  IdentityResult,
  Scenario,
  StatusResponse,
} from "./types";

export class ApiError extends Error {
  status: number;
  constructor(message: string, status: number) {
    super(message);
    this.name = "ApiError";
    this.status = status;
  }
}

const USE_MOCKS = import.meta.env.VITE_USE_MOCKS === "true";

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, {
      ...init,
      headers: {
        Accept: "application/json",
        ...(init?.body ? { "Content-Type": "application/json" } : {}),
        ...(init?.headers ?? {}),
      },
    });
  } catch {
    throw new ApiError(
      "Could not reach the DealScope server. Check that it is running and try again.",
      0,
    );
  }
  if (!res.ok) {
    let detail = `Request failed (HTTP ${res.status}).`;
    try {
      const body: unknown = await res.json();
      if (body && typeof body === "object" && "detail" in body) {
        const d = (body as { detail: unknown }).detail;
        if (typeof d === "string" && d.length > 0) detail = d;
        else if (Array.isArray(d) && d.length > 0) {
          detail = d
            .map((item: unknown) =>
              item && typeof item === "object" && "msg" in item
                ? String((item as { msg: unknown }).msg)
                : String(item),
            )
            .join("; ");
        }
      }
    } catch {
      /* non-JSON error body: keep the generic message */
    }
    throw new ApiError(detail, res.status);
  }
  try {
    return (await res.json()) as T;
  } catch {
    throw new ApiError("The server returned an unreadable response.", res.status);
  }
}

function post<T>(path: string, body?: unknown): Promise<T> {
  return request<T>(path, {
    method: "POST",
    body: body === undefined ? undefined : JSON.stringify(body),
  });
}

// Mocks are loaded lazily and only when VITE_USE_MOCKS is "true"; the condition is a
// build-time constant so production bundles drop the mock code entirely.
const loadMocks = () => import("../mocks/mockApi");

export const api = {
  status: async (): Promise<StatusResponse> =>
    USE_MOCKS ? (await loadMocks()).status() : request<StatusResponse>("/api/status"),
  scenarios: async (): Promise<Scenario[]> =>
    USE_MOCKS ? (await loadMocks()).scenarios() : request<Scenario[]>("/api/scenarios"),
  faults: async (): Promise<FaultOption[]> =>
    USE_MOCKS ? (await loadMocks()).faults() : request<FaultOption[]>("/api/faults"),
  identityCheck: async (domains: string[]): Promise<IdentityResult[]> =>
    USE_MOCKS
      ? (await loadMocks()).identityCheck(domains)
      : post<IdentityResult[]>("/api/identity-check", { domains }),
  createCase: async (req: CreateCaseRequest): Promise<CreateCaseResponse> =>
    USE_MOCKS ? (await loadMocks()).createCase() : post<CreateCaseResponse>("/api/cases", req),
  resumeCase: async (id: string): Promise<CreateCaseResponse> =>
    USE_MOCKS
      ? (await loadMocks()).createCase()
      : post<CreateCaseResponse>(`/api/cases/${encodeURIComponent(id)}/resume`),
  listCases: async (): Promise<CaseListItem[]> =>
    USE_MOCKS ? (await loadMocks()).listCases() : request<CaseListItem[]>("/api/cases"),
  getCase: async (id: string): Promise<CaseView> =>
    USE_MOCKS
      ? (await loadMocks()).getCase(id)
      : request<CaseView>(`/api/cases/${encodeURIComponent(id)}`),
  reportUrl: (id: string): string => `/api/cases/${encodeURIComponent(id)}/report.md`,
  bundleUrl: (id: string): string => `/api/cases/${encodeURIComponent(id)}/bundle.json`,
};

export function errorMessage(e: unknown): string {
  if (e instanceof Error) return e.message;
  return "Something went wrong.";
}

import { useState, type ReactNode } from "react";
import type { RunMode, Tone } from "../api/types";

export function Icon({ name, size = 18 }: { name: "info" | "warn" | "check" | "x" | "download" | "copy" | "external" | "play"; size?: number }) {
  const common = {
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: 2,
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
    "aria-hidden": true,
    focusable: false,
  };
  switch (name) {
    case "info":
      return (
        <svg {...common}>
          <circle cx="12" cy="12" r="9" />
          <path d="M12 11v6M12 7.5v.01" />
        </svg>
      );
    case "warn":
      return (
        <svg {...common}>
          <path d="M12 3l10 18H2L12 3z" />
          <path d="M12 10v5M12 18v.01" />
        </svg>
      );
    case "check":
      return (
        <svg {...common}>
          <path d="M4 12l5 5L20 6" />
        </svg>
      );
    case "x":
      return (
        <svg {...common}>
          <path d="M6 6l12 12M18 6L6 18" />
        </svg>
      );
    case "download":
      return (
        <svg {...common}>
          <path d="M12 4v11M7 11l5 5 5-5M5 20h14" />
        </svg>
      );
    case "copy":
      return (
        <svg {...common}>
          <rect x="9" y="9" width="11" height="11" rx="2" />
          <path d="M5 15V6a2 2 0 012-2h9" />
        </svg>
      );
    case "external":
      return (
        <svg {...common}>
          <path d="M14 4h6v6M20 4l-9 9M18 14v5a1 1 0 01-1 1H5a1 1 0 01-1-1V7a1 1 0 011-1h5" />
        </svg>
      );
    case "play":
      return (
        <svg {...common}>
          <path d="M7 4l13 8-13 8V4z" />
        </svg>
      );
  }
}

export function StatusPill({ tone, children }: { tone: Tone; children: ReactNode }) {
  return <span className={`pill tone-${tone}`}>{children}</span>;
}

export function ModeBadge({ mode, large = false }: { mode: RunMode; large?: boolean }) {
  if (mode === "synthetic") {
    return (
      <span className={`badge mode-synthetic${large ? " banner-demo" : ""}`}>Synthetic demo data</span>
    );
  }
  return <span className="badge mode-live">Live data</span>;
}

export function Banner({ tone, title, children, className = "" }: { tone: Tone; title?: string; children?: ReactNode; className?: string }) {
  return (
    <div className={`banner tone-${tone} ${className}`} role={tone === "bad" ? "alert" : "note"}>
      <Icon name={tone === "bad" || tone === "caution" ? "warn" : "info"} />
      <div>
        {title ? <strong>{title}</strong> : null}
        {children ? <p>{children}</p> : null}
      </div>
    </div>
  );
}

export function Loading({ label = "Loading..." }: { label?: string }) {
  return (
    <div className="state" role="status" aria-live="polite">
      <div className="spinner" aria-hidden="true" />
      <div>{label}</div>
    </div>
  );
}

export function ErrorBox({ title = "Something went wrong", message, onRetry }: { title?: string; message: string; onRetry?: () => void }) {
  return (
    <div className="error-box" role="alert">
      <strong>{title}</strong>
      <span>{message}</span>
      {onRetry ? (
        <div style={{ marginTop: 8 }}>
          <button type="button" className="btn small" onClick={onRetry}>
            Try again
          </button>
        </div>
      ) : null}
    </div>
  );
}

export function EmptyBox({ children }: { children: ReactNode }) {
  return <div className="empty-box">{children}</div>;
}

export function Disclosure({ summary, children, defaultOpen = false }: { summary: ReactNode; children: ReactNode; defaultOpen?: boolean }) {
  return (
    <details className="disclosure" open={defaultOpen}>
      <summary>{summary}</summary>
      <div className="disc-body">{children}</div>
    </details>
  );
}

export function CopyButton({ text, label = "Copy" }: { text: string; label?: string }) {
  const [state, setState] = useState<"idle" | "done" | "failed">("idle");
  const onClick = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setState("done");
    } catch {
      setState("failed");
    }
    window.setTimeout(() => setState("idle"), 1800);
  };
  return (
    <button type="button" className="btn small" onClick={onClick} aria-label={`${label} ${text}`}>
      <Icon name={state === "done" ? "check" : "copy"} size={14} />
      <span aria-live="polite">{state === "done" ? "Copied" : state === "failed" ? "Copy failed" : label}</span>
    </button>
  );
}

export function Meter({
  name,
  valueText,
  percent,
  tone,
  sub,
}: {
  name: string;
  valueText: string;
  percent: number | null;
  tone: Tone;
  sub?: string;
}) {
  const pct = percent === null ? 0 : Math.max(0, Math.min(100, percent));
  return (
    <div className={`tone-${tone}`}>
      <div className="meter-head">
        <span className="meter-name">{name}</span>
        <span className="meter-val">{valueText}</span>
      </div>
      <div
        className="meter-track"
        role="meter"
        aria-label={name}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={percent === null ? undefined : Math.round(pct)}
        aria-valuetext={valueText}
      >
        <div className="meter-fill" style={{ width: `${pct}%` }} />
      </div>
      {sub ? <div className="meter-sub">{sub}</div> : null}
    </div>
  );
}

export function SectionHead({ id, title, subtitle }: { id?: string; title: string; subtitle?: string }) {
  return (
    <div className="section-head">
      <h2 id={id}>{title}</h2>
      {subtitle ? <p>{subtitle}</p> : null}
    </div>
  );
}
const nf = new Intl.NumberFormat("en-US");

export function formatInt(n: number | null | undefined): string {
  if (n === null || n === undefined || Number.isNaN(n)) return "n/a";
  return nf.format(Math.round(n));
}

export function formatCredits(n: number | null | undefined): string {
  if (n === null || n === undefined || Number.isNaN(n)) return "n/a";
  const rounded = Math.round(n * 10) / 10;
  return nf.format(rounded);
}

/** Signed percentage with one decimal, e.g. +12.3% / -4.0%. Input is already a percent value. */
export function formatSignedPct(n: number | null | undefined): string {
  if (n === null || n === undefined || Number.isNaN(n)) return "n/a";
  const sign = n > 0 ? "+" : n < 0 ? "-" : "";
  return `${sign}${Math.abs(n).toFixed(1)}%`;
}

export function formatPct(n: number | null | undefined, digits = 0): string {
  if (n === null || n === undefined || Number.isNaN(n)) return "n/a";
  return `${n.toFixed(digits)}%`;
}

/** Ratio in 0..1 formatted as percent. */
export function formatRate(n: number | null | undefined): string {
  if (n === null || n === undefined || Number.isNaN(n)) return "n/a";
  return `${Math.round(n * 100)}%`;
}

export function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}

function parseDate(iso: string | null | undefined): Date | null {
  if (!iso) return null;
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? null : d;
}

export function formatDate(iso: string | null | undefined): string {
  const d = parseDate(iso);
  if (!d) return iso ? iso : "n/a";
  return d.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}

export function formatDateTime(iso: string | null | undefined): string {
  const d = parseDate(iso);
  if (!d) return iso ? iso : "n/a";
  return d.toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

export function formatTime(iso: string | null | undefined): string {
  const d = parseDate(iso);
  if (!d) return "";
  return d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", second: "2-digit" });
}

export function formatRelative(iso: string | null | undefined, now: number = Date.now()): string {
  const d = parseDate(iso);
  if (!d) return "n/a";
  const diff = Math.round((now - d.getTime()) / 1000);
  if (diff < 0) return "just now";
  if (diff < 45) return "just now";
  if (diff < 90) return "a minute ago";
  const mins = Math.round(diff / 60);
  if (mins < 60) return `${mins} minutes ago`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return hours === 1 ? "1 hour ago" : `${hours} hours ago`;
  const days = Math.round(hours / 24);
  if (days < 30) return days === 1 ? "yesterday" : `${days} days ago`;
  return formatDate(iso);
}

export function plural(n: number, one: string, many?: string): string {
  return n === 1 ? one : (many ?? `${one}s`);
}

/** Encode each path segment after the leading "evidence/" for the evidence endpoint. */
export function evidenceUrl(repoPath: string): string {
  const rel = repoPath.replace(/^\/+/, "").replace(/^evidence\//, "");
  return "/api/evidence/" + rel.split("/").map(encodeURIComponent).join("/");
}

/** Normalize a user-entered domain: strip protocol, www, paths, whitespace, lowercase. */
export function normalizeDomain(raw: string): string {
  let s = raw.trim().toLowerCase();
  s = s.replace(/^[a-z]+:\/\//, "");
  s = s.replace(/^www\./, "");
  s = s.split(/[/?#]/)[0] ?? "";
  return s.replace(/[,;]+$/, "");
}

const DOMAIN_RE = /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/;

export function isValidDomain(d: string): boolean {
  return DOMAIN_RE.test(d);
}

export function splitDomains(text: string): string[] {
  return text
    .split(/[\s,;]+/)
    .map(normalizeDomain)
    .filter((d) => d.length > 0);
}
import { useCallback, useEffect, useRef, useState } from "react";
import { api, errorMessage } from "../api/client";
import type { CaseView } from "../api/types";

export interface AsyncState<T> {
  data: T | null;
  error: string | null;
  loading: boolean;
  reload: () => void;
}

/** Load data once on mount (and whenever `reload` is called). Ignores results after unmount. */
export function useAsync<T>(loader: () => Promise<T>): AsyncState<T> {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [tick, setTick] = useState(0);
  const loaderRef = useRef(loader);
  loaderRef.current = loader;

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    loaderRef.current().then(
      (d) => {
        if (cancelled) return;
        setData(d);
        setLoading(false);
      },
      (e: unknown) => {
        if (cancelled) return;
        setError(errorMessage(e));
        setLoading(false);
      },
    );
    return () => {
      cancelled = true;
    };
  }, [tick]);

  const reload = useCallback(() => setTick((t) => t + 1), []);
  return { data, error, loading, reload };
}

const POLL_MS = 1500;

export interface CaseState {
  data: CaseView | null;
  error: string | null;
  loading: boolean;
  refresh: () => void;
}

/**
 * Fetches a case and keeps polling every ~1.5 s while the case reports running = true.
 * Exactly one timer exists at a time and it is cleared on unmount or id change.
 */
export function useCase(id: string): CaseState {
  const [data, setData] = useState<CaseView | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [kick, setKick] = useState(0);

  useEffect(() => {
    let cancelled = false;
    let timer: number | undefined;
    let lastRunning = false;

    const run = async () => {
      try {
        const view = await api.getCase(id);
        if (cancelled) return;
        setData(view);
        setError(null);
        setLoading(false);
        lastRunning = view.running;
        if (view.running) {
          timer = window.setTimeout(run, POLL_MS);
        }
      } catch (e) {
        if (cancelled) return;
        setError(errorMessage(e));
        setLoading(false);
        // Keep trying while we previously saw a running case; a transient failure should not freeze the page.
        if (lastRunning) timer = window.setTimeout(run, POLL_MS * 3);
      }
    };

    setLoading(true);
    run();
    return () => {
      cancelled = true;
      if (timer !== undefined) window.clearTimeout(timer);
    };
  }, [id, kick]);

  const refresh = useCallback(() => setKick((k) => k + 1), []);
  return { data, error, loading, refresh };
}

/** Re-render periodically so relative timestamps stay fresh. */
export function useNow(intervalMs = 30000): number {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const t = window.setInterval(() => setNow(Date.now()), intervalMs);
    return () => window.clearInterval(t);
  }, [intervalMs]);
  return now;
}

export function useDocumentTitle(title: string): void {
  useEffect(() => {
    document.title = title ? `${title} - DealScope` : "DealScope";
  }, [title]);
}
