.signal-head { display: flex; justify-content: space-between; gap: 10px; align-items: flex-start; }
.signal-name { font-size: 1.02rem; margin: 0; }
.signal-q { color: var(--muted); font-size: 0.88rem; margin: 2px 0 10px; font-style: italic; }
.bar-row { display: flex; align-items: center; gap: 10px; margin: 6px 0; }
.bar-track { flex: 1; height: 10px; border-radius: 999px; background: var(--neutral-bg); overflow: hidden; }
.bar-fill { height: 100%; background: var(--tone-bar); border-radius: 999px; }
.bar-val { font-weight: 700; min-width: 4.5em; text-align: right; font-variant-numeric: tabular-nums; font-size: 0.9rem; }
.kv { display: flex; gap: 14px; flex-wrap: wrap; color: var(--muted); font-size: 0.84rem; margin-bottom: 8px; }
.signal .finding-text-plain { margin-bottom: 8px; }
.signal h4 { margin: 10px 0 2px; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }
.signal ul.lim { color: var(--ink-2); font-size: 0.88rem; margin: 2px 0 0; }
.tech-list { font-family: var(--mono); font-size: 0.8rem; word-break: break-word; }

/* Findings */
.finding-group + .finding-group { margin-top: 20px; }
.finding-group > h3 { display: flex; gap: 8px; align-items: baseline; }
.finding-group > h3 .muted { font-weight: 400; font-size: 0.85rem; }
.finding { margin-top: 10px !important; border-left: 4px solid var(--tone-bar); padding: 14px 16px; }
.finding-top { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-bottom: 6px; }
.finding-text { font-weight: 600; margin: 0 0 8px; font-size: 1rem; }
.finding h4 { margin: 10px 0 2px; font-size: 0.85rem; color: var(--ink-2); }
.finding ul { margin: 2px 0 0; font-size: 0.9rem; color: var(--ink-2); }
.ev-list { list-style: none; padding: 0 !important; }
.ev-item { padding: 6px 10px; background: var(--surface-2); border-radius: var(--radius-sm); margin-bottom: 4px; border-left: 3px solid var(--good-bar); }
.ev-item.counter { border-left-color: var(--bad-bar); background: var(--bad-bg); }
.ev-label { font-weight: 600; font-size: 0.88rem; color: var(--ink); }
.ev-meta { color: var(--muted); font-size: 0.8rem; }
.ev-item.counter .ev-meta { color: var(--bad-fg); }

/* Questions */
.question-list { padding-left: 0; list-style: none; counter-reset: q; }
.question-list li { counter-increment: q; display: flex; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--line); margin: 0; }
.question-list li:last-child { border-bottom: 0; }
.question-list li::before {
  content: counter(q); flex: none; width: 26px; height: 26px; border-radius: 50%; background: var(--accent-soft); color: var(--accent);
  font-weight: 700; display: inline-flex; align-items: center; justify-content: center; font-size: 0.85rem;
}

/* Timeline */
.timeline { list-style: none; padding: 0; margin: 0; position: relative; }
.timeline li { position: relative; padding: 0 0 18px 30px; margin: 0; }
.timeline li::before { content: ""; position: absolute; left: 9px; top: 18px; bottom: -2px; width: 2px; background: var(--line); }
.timeline li:last-child::before { display: none; }
.tl-dot { position: absolute; left: 2px; top: 4px; width: 16px; height: 16px; border-radius: 50%; background: var(--tone-bar); border: 3px solid var(--surface); box-shadow: 0 0 0 1px var(--tone-bar); }
.tl-top { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.tl-title { font-weight: 600; }
.tl-detail { color: var(--ink-2); margin: 2px 0 0; font-size: 0.9rem; }
.tl-meta { color: var(--muted); font-size: 0.8rem; display: flex; gap: 12px; flex-wrap: wrap; margin-top: 2px; }
.actor { font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; padding: 1px 8px; border-radius: 4px; background: var(--tone-bg); color: var(--tone-fg); }

/* Progress */
.progress-panel { border-left: 5px solid var(--accent); }
.progress-q { font-size: 1.05rem; font-weight: 600; margin: 6px 0 12px; }
.spinner {
  width: 18px; height: 18px; border-radius: 50%; border: 3px solid var(--line-strong); border-top-color: var(--accent);
  animation: spin 0.9s linear infinite; display: inline-block; flex: none;
}
@keyframes spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .spinner { animation-duration: 3s; } html { scroll-behavior: auto; } }
.progress-head { display: flex; align-items: center; gap: 10px; font-weight: 700; }
.live-steps { max-height: 320px; overflow: auto; margin-top: 8px; padding-top: 4px; }

/* Cost */
.stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }
.stat { background: var(--surface-2); border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 10px 12px; }
.stat-v { font-size: 1.4rem; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1.2; }
.stat-k { color: var(--muted); font-size: 0.82rem; }
.cols-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.cols-2 > .card { margin: 0 !important; }
.trace-row { display: flex; gap: 8px; align-items: center; margin-bottom: 6px; flex-wrap: wrap; }
.trace-id { font-family: var(--mono); font-size: 0.82rem; background: var(--surface-2); border: 1px solid var(--line); padding: 3px 8px; border-radius: 4px; word-break: break-all; }

/* States */
.state { text-align: center; padding: 36px 16px; color: var(--muted); }
.state .spinner { margin-bottom: 8px; }
.error-box { background: var(--bad-bg); color: var(--bad-fg); border: 1px solid var(--bad-bar); border-radius: var(--radius); padding: 12px 14px; }
.error-box strong { display: block; }
.empty-box { padding: 18px; text-align: center; color: var(--muted); border: 1px dashed var(--line-strong); border-radius: var(--radius); background: var(--surface); }

/* Cases list */
.case-link { font-weight: 600; text-decoration: none; }
.case-link:hover { text-decoration: underline; }

/* How it works */
.hiw { display: grid; grid-template-columns: 240px 1fr; gap: 32px; align-items: start; }
.toc { position: sticky; top: 84px; max-height: calc(100vh - 100px); overflow: auto; }
.toc h2 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); }
.toc ol { list-style: none; padding: 0; margin: 0; border-left: 2px solid var(--line); }
.toc a { display: block; padding: 5px 12px; margin-left: -2px; border-left: 2px solid transparent; text-decoration: none; color: var(--ink-2); font-size: 0.88rem; }
.toc a:hover { color: var(--accent); }
.toc a.active { border-left-color: var(--accent); color: var(--accent); font-weight: 600; }
.hiw-intro { font-size: 1.1rem; color: var(--ink-2); max-width: 70ch; }
.hiw-section { margin-top: 36px; scroll-margin-top: 80px; }
.hiw-section:first-of-type { margin-top: 20px; }
.hiw-section .summary-line { font-size: 1.02rem; color: var(--ink-2); font-weight: 500; }
.hiw-section p { max-width: 74ch; }
.figure { margin: 16px 0; }
.figure a { display: block; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: var(--surface); }
.figure img { display: block; max-width: 100%; height: auto; margin: 0 auto; }
.figure figcaption { color: var(--muted); font-size: 0.85rem; margin-top: 6px; }

@media (max-width: 900px) {
  .summary { grid-template-columns: 1fr; gap: 18px; }
  .hiw { grid-template-columns: 1fr; }
  .toc { position: static; max-height: none; }
  .cols-2 { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .grid-2, .meters { grid-template-columns: 1fr; }
  .signals { grid-template-columns: 1fr; }
  .card { padding: 16px 14px; }
  .score-num { font-size: 3.2rem; }
  .main { padding-top: 16px; }
  .systems-panel { right: -8px; }
  .topbar-inner { gap: 6px 12px; }
  h1 { font-size: 1.35rem; }
}
@media print { .topbar, .footer { display: none; } }

// Dev-only mock backend, used only when VITE_USE_MOCKS === "true" (see src/api/client.ts).
import type {
  CaseListItem,
  CaseView,
  CreateCaseResponse,
  FaultOption,
  IdentityResult,
  Scenario,
  StatusResponse,
} from "../api/types";
import { sampleCase } from "./sampleCase";

const delay = <T>(v: T, ms = 250): Promise<T> => new Promise((r) => window.setTimeout(() => r(v), ms));

export function status(): Promise<StatusResponse> {
  return delay({
    providers: [
      { key: "crustdata", label: "Company data (Crustdata)", connected: true, detail: "Connected" },
      { key: "llm", label: "AI model", connected: true, detail: "Model: gemini-3.1-flash-lite" },
      { key: "neatlogs", label: "Tracing (Neatlogs)", connected: false, detail: "Not configured" },
      { key: "jobs_pricing", label: "Job-posting pricing", connected: true, detail: "Connected" },
    ],
    live_budget: { spendable: 150, estimated_used: 10, actual_used: 8, reserved: 0, remaining: 140, unknown_calls: 0, reserve: 50, total: 200 },
    max_case_credits: 60,
    live_available: true,
  });
}

export function scenarios(): Promise<Scenario[]> {
  return delay([
    { id: "scenario_a", label: "Engineering slowdown", description: "A target whose engineering team lags company growth.", target_domain: "northwind.example", competitor_domains: ["contoso.example", "fabrikam.example"], deal_thesis: "We expect the engineering team to keep pace with company growth after the acquisition." },
    { id: "scenario_b", label: "Leadership exits", description: "A target losing senior technical leaders to a competitor.", target_domain: "tailspin.example", competitor_domains: ["wingtip.example", "litware.example", "adatum.example"], deal_thesis: "No key technical leaders are likely to leave within a year of closing." },
  ]);
}

export function faults(): Promise<FaultOption[]> {
  return delay([
    { id: "none", label: "None", description: "Run normally." },
    { id: "retry_success", label: "Temporary outage, then recovery", description: "A data source fails once, then works on retry." },
    { id: "retry_exhausted", label: "Persistent outage", description: "A data source keeps failing; the agent must continue with less data." },
    { id: "auth_failure", label: "Authentication failure", description: "The data source rejects credentials; the run stops safely and can be resumed." },
  ]);
}

export function identityCheck(domains: string[]): Promise<IdentityResult[]> {
  return delay(
    domains.map((d, i): IdentityResult =>
      i === 1
        ? {
            domain: d, ok: false, status: "ambiguous", resolved_name: null, match_count: 23,
            message: "23 different companies use this domain. Pick the one you mean.",
            candidates: [
              { name: "Contoso Labs", primary_domain: "contoso-labs.example", employee_count_range: "1001-5000" },
              { name: "Contoso Group", primary_domain: null, employee_count_range: null },
            ],
          }
        : { domain: d, ok: true, status: "ok", resolved_name: d.split(".")[0], match_count: 1, message: "Matched one company.", candidates: [] },
    ),
  );
}

export function createCase(): Promise<CreateCaseResponse> {
  startedAt = Date.now();
  return delay({ case_id: sampleCase.case_id });
}

export function listCases(): Promise<CaseListItem[]> {
  return delay([
    { case_id: sampleCase.case_id, target: sampleCase.target, mode: "synthetic", status_label: "Complete", tone: "good", risk_label: "Watch (41/100)", updated_at: sampleCase.updated_at },
    { case_id: "case_live_0002", target: "notion.com", mode: "live", status_label: "Partial - can resume", tone: "caution", risk_label: "Not enough evidence", updated_at: new Date(Date.now() - 3600_000).toISOString() },
  ]);
}

let startedAt = 0;

export function getCase(id: string): Promise<CaseView> {
  // After creating a case, simulate ~6 s of running before the sample completes.
  const elapsed = Date.now() - startedAt;
  if (startedAt > 0 && elapsed < 6000) {
    const n = Math.max(1, Math.min(sampleCase.steps.length, Math.ceil(elapsed / 1200)));
    return delay({
      ...sampleCase,
      case_id: id,
      running: true,
      status_label: "Running",
      status_tone: "info",
      status_detail: "The investigation is in progress.",
      current_question: "Is the engineering team keeping pace with the company?",
      assessment: null,
      report_available: false,
      steps: sampleCase.steps.slice(0, n),
    });
  }
  return delay({ ...sampleCase, case_id: id });
}
import { Link } from "react-router-dom";
import { api } from "../api/client";
import { EmptyBox, ErrorBox, Loading, ModeBadge, StatusPill } from "../components/ui";
import { formatDateTime, formatRelative } from "../lib/format";
import { useAsync, useDocumentTitle, useNow } from "../lib/hooks";

export function Cases() {
  useDocumentTitle("Cases");
  const { data, error, loading, reload } = useAsync(() => api.listCases());
  const now = useNow();

  const items = data ? [...data].sort((a, b) => b.updated_at.localeCompare(a.updated_at)) : [];

  return (
    <>
      <div className="page-head">
        <h1>Cases</h1>
        <p>Every investigation that has been run, newest first. Open one to see its summary, evidence and memo.</p>
      </div>

      {loading ? (
        <Loading label="Loading cases..." />
      ) : error ? (
        <ErrorBox title="Could not load cases" message={error} onRetry={reload} />
      ) : items.length === 0 ? (
        <EmptyBox>
          No investigations yet. <Link to="/">Start your first investigation</Link>.
        </EmptyBox>
      ) : (
        <div className="table-wrap">
          <table>
            <caption className="sr-only">Investigations</caption>
            <thead>
              <tr>
                <th scope="col">Target</th>
                <th scope="col">Status</th>
                <th scope="col">Risk result</th>
                <th scope="col">Data</th>
                <th scope="col">Last updated</th>
              </tr>
            </thead>
            <tbody>
              {items.map((c) => (
                <tr key={c.case_id}>
                  <td>
                    <Link className="case-link" to={`/cases/${encodeURIComponent(c.case_id)}`}>
                      {c.target}
                    </Link>
                  </td>
                  <td>
                    <StatusPill tone={c.tone}>{c.status_label}</StatusPill>
                  </td>
                  <td>{c.risk_label}</td>
                  <td>
                    <ModeBadge mode={c.mode} />
                  </td>
                  <td>
                    <time dateTime={c.updated_at} title={formatDateTime(c.updated_at)}>
                      {formatRelative(c.updated_at, now)}
                    </time>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </>
  );
}
import { Link, useParams } from "react-router-dom";
import { CaseHeader } from "../components/CaseHeader";
import { CostTrust } from "../components/CostTrust";
import { EvidenceTabs } from "../components/EvidenceTabs";
import { FindingsSection } from "../components/FindingsSection";
import { ProgressPanel } from "../components/ProgressPanel";
import { QuestionsSection } from "../components/QuestionsSection";
import { SignalsSection } from "../components/SignalsSection";
import { StepTimeline } from "../components/StepTimeline";
import { SummaryCard } from "../components/SummaryCard";
import { EmptyBox, ErrorBox, Loading, SectionHead } from "../components/ui";
import { useCase, useDocumentTitle } from "../lib/hooks";

export function CaseDetail() {
  const { id = "" } = useParams<{ id: string }>();
  const { data, error, loading, refresh } = useCase(id);
  useDocumentTitle(data ? `${data.target} investigation` : "Case");

  if (loading && !data) {
    return <Loading label="Loading case..." />;
  }
  if (!data) {
    return (
      <>
        <ErrorBox title="Could not load this case" message={error ?? "The case was not found."} onRetry={refresh} />
        <p style={{ marginTop: 14 }}>
          <Link to="/cases">Back to all cases</Link>
        </p>
      </>
    );
  }

  const v = data;
  return (
    <>
      <p className="small" style={{ marginBottom: 10 }}>
        <Link to="/cases">All cases</Link>
      </p>
      {error ? (
        <div style={{ marginBottom: 12 }}>
          <ErrorBox title="Live updates interrupted" message={`${error} Retrying automatically.`} />
        </div>
      ) : null}

      <CaseHeader view={v} onResumed={refresh} />

      {v.running ? <ProgressPanel view={v} /> : null}

      <div className="section" style={{ marginTop: 16 }}>
        <SummaryCard assessment={v.assessment} running={v.running} />
      </div>

      <SignalsSection signals={v.signals} />
      <FindingsSection findings={v.findings} />
      <QuestionsSection questions={v.questions} />

      <section className="section" aria-labelledby="steps-h">
        <SectionHead
          id="steps-h"
          title="How the agent investigated"
          subtitle="A step-by-step record. The AI planner chooses what to look up; the rule-based planner is the fixed fallback; the system handles everything else."
        />
        <div className="card">
          {v.steps.length === 0 ? (
            <EmptyBox>No steps have been recorded yet.</EmptyBox>
          ) : (
            <StepTimeline steps={v.steps} />
          )}
        </div>
      </section>

      <EvidenceTabs companies={v.companies} people={v.people} jobs={v.jobs} />
      <CostTrust
        credits={v.credits}
        verification={v.verification}
        llmModel={v.llm_model}
        traceIds={v.trace_ids}
        synthetic={v.synthetic}
      />
    </>
  );
}
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { api, errorMessage } from "../api/client";
import type { CaseView } from "../api/types";
import { formatDateTime } from "../lib/format";
import { Banner, Disclosure, Icon, ModeBadge, StatusPill } from "./ui";

interface Props {
  view: CaseView;
  onResumed: () => void;
}

export function CaseHeader({ view, onResumed }: Props) {
  const navigate = useNavigate();
  const [resuming, setResuming] = useState(false);
  const [resumeError, setResumeError] = useState<string | null>(null);

  const resume = async () => {
    setResuming(true);
    setResumeError(null);
    try {
      const res = await api.resumeCase(view.case_id);
      if (res.case_id && res.case_id !== view.case_id) {
        navigate(`/cases/${encodeURIComponent(res.case_id)}`);
      } else {
        onResumed();
      }
    } catch (e) {
      setResumeError(errorMessage(e));
    } finally {
      setResuming(false);
    }
  };

  return (
    <header className="card case-head">
      {view.synthetic ? (
        <Banner tone="caution" className="banner-demo" title="Demo data - not a real company assessment">
          The companies, people and job postings below are fictional. Do not use these results to judge a real business.
        </Banner>
      ) : null}

      <div className="case-meta">
        <ModeBadge mode={view.mode} />
        <StatusPill tone={view.status_tone}>{view.status_label}</StatusPill>
        <span className="muted small">
          Updated <time dateTime={view.updated_at}>{formatDateTime(view.updated_at)}</time>
        </span>
      </div>

      <h1>{view.target}</h1>
      <p className="peer-list">
        <strong>Compared with:</strong> {view.peers.length > 0 ? view.peers.join(", ") : "no peers listed"}
        <span className="muted"> - last {view.lookback_months} months</span>
      </p>

      {view.status_detail ? <p className="muted" style={{ marginBottom: 8 }}>{view.status_detail}</p> : null}

      <Disclosure summary="Deal thesis">
        <blockquote className="thesis" style={{ margin: 0 }}>
          {view.thesis}
        </blockquote>
      </Disclosure>

      <div className="btn-row" style={{ marginTop: 14 }}>
        {view.can_resume ? (
          <button type="button" className="btn primary" onClick={resume} disabled={resuming}>
            <Icon name="play" size={14} />
            {resuming ? "Resuming..." : "Resume investigation"}
          </button>
        ) : null}
        {view.report_available ? (
          <>
            <a className="btn" href={api.reportUrl(view.case_id)} download>
              <Icon name="download" size={16} />
              Memo (.md)
            </a>
            <a className="btn" href={api.bundleUrl(view.case_id)} download>
              <Icon name="download" size={16} />
              Evidence (.json)
            </a>
          </>
        ) : null}
      </div>
      {resumeError ? (
        <p className="error-text" role="alert">
          {resumeError}
        </p>
      ) : null}
    </header>
  );
}
import type { CaseView } from "../api/types";
